                    if score < best_score - 1e-12:
                        best_score = score
                        best_i = i
                        best_last = lasts[i]
                    elif abs(score - best_score) <= 1e-12 and lasts[i] > best_last:
                        best_i = i
                        best_last = lasts[i]
                return best_i

